changeSet.sql:
DELETE FROM rings WHERE id > -1 AND id IN (
    SELECT ringid FROM inventoryequipment WHERE inventoryitemid IN (
        SELECT inventoryitemid FROM inventoryitems
        WHERE characterid IN (SELECT c.id FROM characters c JOIN accounts a ON a.id = c.accountid WHERE LOWER(a.`name`) = 'admin')
           OR accountid IN (SELECT id FROM accounts WHERE LOWER(`name`) = 'admin')));
DELETE FROM pets WHERE petid IN (
    SELECT petid FROM inventoryitems
    WHERE petid > -1
      AND (characterid IN (SELECT c.id FROM characters c JOIN accounts a ON a.id = c.accountid WHERE LOWER(a.`name`) = 'admin')
           OR accountid IN (SELECT id FROM accounts WHERE LOWER(`name`) = 'admin')));
DELETE FROM inventoryequipment WHERE inventoryitemid IN (
    SELECT inventoryitemid FROM inventoryitems
    WHERE characterid IN (SELECT c.id FROM characters c JOIN accounts a ON a.id = c.accountid WHERE LOWER(a.`name`) = 'admin')
       OR accountid IN (SELECT id FROM accounts WHERE LOWER(`name`) = 'admin'));
DELETE FROM inventoryitems
    WHERE characterid IN (SELECT c.id FROM characters c JOIN accounts a ON a.id = c.accountid WHERE LOWER(a.`name`) = 'admin')
       OR accountid IN (SELECT id FROM accounts WHERE LOWER(`name`) = 'admin');
DELETE FROM inventorymerchant WHERE characterid IN (SELECT c.id FROM characters c JOIN accounts a ON a.id = c.accountid WHERE LOWER(a.`name`) = 'admin');

